package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"sort"
	"strings"
	"time"
)

var templates = []string{"/", "/a", "/a/b", "/a/b/c", "/:id", "/:id/x", "/:id/:id2", "/a/:id", "/a/:id/b", "/*", "/a/*", "/a/b/*", "/:id/*"}

func templateMatches(tmpl, path string) bool {
	if i := strings.Index(tmpl, "*"); i >= 0 {
		return strings.HasPrefix(path, tmpl[:i])
	}
	ts := strings.Split(tmpl, "/")
	ps := strings.Split(path, "/")
	if len(ts) != len(ps) {
		return false
	}
	for i := range ts {
		if strings.HasPrefix(ts[i], ":") {
			if ps[i] == "" {
				return false
			}
			continue
		}
		if ts[i] != ps[i] {
			return false
		}
	}
	return true
}

func concretePaths(tmpl string) []string {
	out := []string{}
	base := strings.NewReplacer(":id2", "y", ":id", "x").Replace(tmpl)
	if strings.Contains(tmpl, "*") {
		for _, rep := range []string{"z", "z/w", ""} {
			out = append(out, strings.Replace(base, "*", rep, 1))
		}
	} else {
		out = append(out, base)
	}
	return out
}
