package main

import (
	"fmt"
	"net/http"
	"net/url"
	"regexp"
	"runtime/debug"
	"strings"
	"time"

	"github.com/labstack/echo/v4"
)

// templates used for systematic combination
var templates = []string{
	"/", "/a", "/a/b", "/a/b/c", "/:id", "/:id/x", "/:id/:id2",
	"/a/:id", "/a/:id/b", "/*", "/a/*", "/a/b/*", "/:id/*",
}

var tmplReCache = map[string]*regexp.Regexp{}

// tmplRegexp models the *documented / expected* echo v4 matching semantics:
//   - ":" segment matches a (possibly empty) run of non-'/' chars, except a
//     trailing ":" segment which requires at least one char
//   - "*" matches the remainder of the path (including '/' and empty)
func tmplRegexp(tmpl string) *regexp.Regexp {
	if re, ok := tmplReCache[tmpl]; ok {
		return re
	}
	t := tmpl
	if t == "" {
		t = "/"
	}
	if !strings.HasPrefix(t, "/") {
		t = "/" + t
	}
	segs := strings.Split(t, "/")
	var b strings.Builder
	b.WriteString("^")
	for i, s := range segs {
		if i > 0 {
			b.WriteString("/")
		}
		switch {
		case s == "*":
			b.WriteString(".*")
		case strings.HasPrefix(s, ":"):
			if i == len(segs)-1 {
				b.WriteString("[^/]+")
			} else {
				b.WriteString("[^/]*")
			}
		default:
			b.WriteString(regexp.QuoteMeta(s))
		}
	}
	b.WriteString("$")
	re := regexp.MustCompile(b.String())
	tmplReCache[tmpl] = re
	return re
}

func matchingTemplates(tmpls []string, path string) []string {
	out := []string{}
	for _, t := range tmpls {
		if tmplRegexp(t).MatchString(path) {
			out = append(out, t)
		}
	}
	return out
}

// concretePaths builds concrete request paths for a template.
func concretePaths(tmpl string) []string {
	repl := func(s string) string {
		s = strings.ReplaceAll(s, ":id2", "y")
		s = strings.ReplaceAll(s, ":id", "x")
		return s
	}
	var out []string
	if strings.Contains(tmpl, "*") {
		out = append(out, repl(strings.Replace(tmpl, "*", "z", 1)))
		out = append(out, repl(strings.Replace(tmpl, "*", "z/w", 1)))
		out = append(out, repl(strings.Replace(tmpl, "*", "", 1)))
	} else {
		out = append(out, repl(tmpl))
	}
	// dedupe
	seen := map[string]bool{}
	var res []string
	for _, p := range out {
		if !seen[p] {
			seen[p] = true
			res = append(res, p)
		}
	}
	return res
}

func buildEcho(tmpls []string) *echo.Echo {
	e := echo.New()
	for _, t := range tmpls {
		tt := t
		e.GET(tt, func(c echo.Context) error {
			return c.String(http.StatusOK, tt)
		})
	}
	return e
}

type result struct {
	code     int
	body     string
	panicVal interface{}
	stack    string
}

// doRequest issues a request through the public API, guarded by a timeout.
func doRequest(e *echo.Echo, method, path, rawPath string) (result, bool) {
	ch := make(chan result, 1)
	go func() {
		r := result{}
		defer func() {
			if p := recover(); p != nil {
				r.panicVal = p
				r.stack = string(debug.Stack())
			}
			ch <- r
		}()
		req := &http.Request{
			Method: method,
			URL:    &url.URL{Path: path, RawPath: rawPath},
			Header: http.Header{},
			Host:   "example.com",
		}
		rec := &recorder{code: 200}
		e.ServeHTTP(rec, req)
		r.code = rec.code
		r.body = rec.body.String()
	}()
	select {
	case r := <-ch:
		return r, false
	case <-time.After(5 * time.Second):
		return result{}, true
	}
}

type recorder struct {
	code   int
	body   strings.Builder
	header http.Header
}

func (r *recorder) Header() http.Header {
	if r.header == nil {
		r.header = http.Header{}
	}
	return r.header
}
func (r *recorder) Write(b []byte) (int, error) { return r.body.Write(b) }
func (r *recorder) WriteHeader(code int)        { r.code = code }

func fmtSet(tmpls []string) string {
	return "{" + strings.Join(tmpls, ", ") + "}"
}

func fmtViolation(tmpls []string, path string, expected string, observed string) string {
	return fmt.Sprintf("routes=%s request=GET %q expected=%s observed=%s", fmtSet(tmpls), path, expected, observed)
}
