package main

import (
	"fmt"
	"strings"
	"testing"
)

const maxReport = 25

type violations struct {
	list  []string
	total int
}

func (v *violations) add(s string) {
	v.total++
	if len(v.list) < maxReport {
		v.list = append(v.list, s)
	}
}

func (v *violations) dump(t *testing.T, name string) {
	for _, s := range v.list {
		t.Errorf("[%s] %s", name, s)
	}
	if v.total > len(v.list) {
		t.Errorf("[%s] ... %d more violations suppressed", name, v.total-len(v.list))
	}
}

// checkSet registers tmpls and verifies reachability + no false matches.
func checkSet(tmpls []string, v *violations) {
	e := buildEcho(tmpls)
	for _, tmpl := range tmpls {
		for _, p := range concretePaths(tmpl) {
			matching := matchingTemplates(tmpls, p)
			res, timedOut := doRequest(e, "GET", p, "")
			if timedOut {
				v.add(fmtViolation(tmpls, p, "response within 5s", "HANG (timeout)"))
				continue
			}
			if res.panicVal != nil {
				v.add(fmtViolation(tmpls, p, "no panic", fmt.Sprintf("PANIC: %v\n%s", res.panicVal, res.stack)))
				continue
			}
			if res.code != 200 {
				v.add(fmtViolation(tmpls, p, fmt.Sprintf("200 from one of %v", matching), fmt.Sprintf("%d body=%q", res.code, res.body)))
				continue
			}
			ok := false
			for _, m := range matching {
				if m == res.body {
					ok = true
				}
			}
			if !ok {
				v.add(fmtViolation(tmpls, p, fmt.Sprintf("marker in %v", matching), fmt.Sprintf("marker %q", res.body)))
			}
		}
	}
	// negative: paths that match no template must 404
	for _, p := range negativePaths {
		if len(matchingTemplates(tmpls, p)) != 0 {
			continue
		}
		res, timedOut := doRequest(e, "GET", p, "")
		if timedOut {
			v.add(fmtViolation(tmpls, p, "response within 5s", "HANG (timeout)"))
			continue
		}
		if res.panicVal != nil {
			v.add(fmtViolation(tmpls, p, "no panic", fmt.Sprintf("PANIC: %v\n%s", res.panicVal, res.stack)))
			continue
		}
		if res.code != 404 {
			v.add(fmtViolation(tmpls, p, "404 (no template matches)", fmt.Sprintf("%d body=%q", res.code, res.body)))
		}
	}
}

var negativePaths = []string{"/b", "/a/b/c/d", "/x/y/z", "/zz", "/a/b/c/d/e", "/x", "/y", "/a/x/y/z"}

func subsets(n, maxSize int, f func([]int)) {
	var rec func(start int, cur []int)
	rec = func(start int, cur []int) {
		if len(cur) > 0 {
			f(append([]int(nil), cur...))
		}
		if len(cur) == maxSize {
			return
		}
		for i := start; i < n; i++ {
			rec(i+1, append(cur, i))
		}
	}
	rec(0, nil)
}

func TestReachabilityAllSubsets(t *testing.T) {
	v := &violations{}
	subsets(len(templates), 5, func(idx []int) {
		set := make([]string, len(idx))
		for i, j := range idx {
			set[i] = templates[j]
		}
		checkSet(set, v)
	})
	checkSet(templates, v)
	v.dump(t, "subsets")
	t.Logf("checked subsets up to size 5: %d violations", v.total)
}

func TestReachabilityPermutations(t *testing.T) {
	v := &violations{}
	subsets(len(templates), 3, func(idx []int) {
		base := make([]string, len(idx))
		for i, j := range idx {
			base[i] = templates[j]
		}
		permute(base, 0, func(p []string) {
			checkSet(p, v)
		})
	})
	v.dump(t, "permutations")
	t.Logf("checked permutations up to size 3: %d violations", v.total)
}

func permute(a []string, k int, f func([]string)) {
	if k == len(a) {
		f(a)
		return
	}
	for i := k; i < len(a); i++ {
		a[k], a[i] = a[i], a[k]
		permute(a, k+1, f)
		a[k], a[i] = a[i], a[k]
	}
}

