206	func setWithProperType(valueKind reflect.Kind, val string, structField reflect.Value) error {
207		// But also call it here, in case we're dealing with an array of BindUnmarshalers
208		if ok, err := unmarshalField(valueKind, val, structField); ok {
209			return err
210		}
211	
212		switch valueKind {
213		case reflect.Ptr:
214			return setWithProperType(structField.Elem().Kind(), val, structField.Elem())
215		case reflect.Int:
216			return setIntField(val, 0, structField)
217		case reflect.Int8:
218			return setIntField(val, 8, structField)
219		case reflect.Int16:
220			return setIntField(val, 16, structField)
221		case reflect.Int32:
222			return setIntField(val, 32, structField)
223		case reflect.Int64:
224			return setIntField(val, 64, structField)
225		case reflect.Uint:
226			return setUintField(val, 0, structField)
227		case reflect.Uint8:
228			return setUintField(val, 8, structField)
229		case reflect.Uint16:
230			return setUintField(val, 16, structField)
231		case reflect.Uint32:
232			return setUintField(val, 32, structField)
233		case reflect.Uint64:
234			return setUintField(val, 64, structField)
235		case reflect.Bool:
236			return setBoolField(val, structField)
237		case reflect.Float32:
238			return setFloatField(val, 32, structField)
239		case reflect.Float64:
240			return setFloatField(val, 64, structField)
241		case reflect.String:
242			structField.SetString(val)
243		default:
244			return errors.New("unknown type")
245		}
246		return nil
247	}
